// GET ?e_sorder_id=S2737687.0001 or S2737687. Without a gen suffix the
// lowest generation on the order is the selected one (genId '').
const q = $input.first().json.query || {};
const m = String(q.e_sorder_id || '').trim().toUpperCase().match(/^S?(\d+)(?:\.(\d{1,4}))?$/);
if (!m) return [{ json: { ok: false, statusCode: 400, body: { success: false, error: 'Missing or invalid e_sorder_id (expected S1234567 or S1234567.0001).', step: 'validate' } } }];
return [{ json: { ok: true, oid: 'S' + m[1], genId: m[2] ? String(Number(m[2])) : '' } }];

// Every generation's e_sorder_id (S2659464.0002, ...) for one HubSpot deal
// Batch Read; the Eclipse response is read again by name in Shape.
const env = $input.first().json;
const so = (Array.isArray(env.results) ? env.results[0] : env) || {};
const oid = $('Validate').first().json.oid;
const ids = (Array.isArray(so.generations) ? so.generations : [])
  .map((g) => oid + '.' + String(g.generationId).padStart(4, '0'));
return [{ json: { ids: ids.join(',') } }];

// Every generation of the order, each with its own header and lines; the
// requested (or lowest) generation's fields are also at the top level.
// Each generation also gets its HubSpot deal (matched on e_sorder_id).
const v = $('Validate').first().json;
const env = $('Eclipse: get order').first().json;
const fail = (statusCode, error, step) => [{ json: { ok: false, statusCode, body: { success: false, error, step } } }];
if (env.error) return fail(502, 'Eclipse GET /SalesOrders?id=' + v.oid + ' failed: ' + env.error + ' ' + JSON.stringify(env.message || '').substring(0, 500), 'getSalesOrder');
const so = (Array.isArray(env.results) ? env.results[0] : env) || {};
if (!Array.isArray(so.generations) || !so.generations.length) return fail(404, 'Eclipse order ' + v.oid + ' not found.', 'getSalesOrder');
const money = (m) => (m && m.value != null ? Number(m.value) : null);
const pad = (g) => String(g).padStart(4, '0');

// HubSpot deals by e_sorder_id (Batch Read, allInOne → { results: [...] }).
const hsResp = $input.first().json || {};
const deals = {};
for (const row of (Array.isArray(hsResp.results) ? hsResp.results : [])) {
  const p = row.properties || {};
  if (p.e_sorder_id) deals[String(p.e_sorder_id).trim().toUpperCase()] = row;
}

// Lines with a quantity, per generation id.
const linesByGen = {};
for (const line of (Array.isArray(so.lines) ? so.lines : [])) {
  for (const lg of (Array.isArray(line.generations) ? line.generations : [])) {
    const qty = (Number(lg.stockQty) || 0) + (Number(lg.nonstockQty) || 0);
    if (qty <= 0) continue;
    const gid = String(lg.generationId);
    (linesByGen[gid] = linesByGen[gid] || []).push({
      line_id: line.lineId, product_id: String(line.productId), qty,
      description: String(line.productDescription || line.productDecription || '').replace(/\s*\n\s*/g, ' ').trim(),
      unit_price: lg.price && lg.price.value != null ? Number(lg.price.value) : null,
      // Line cost and COGS as saved on the order (null when restricted / missing).
      unit_cost: lg.cost && lg.cost.value != null ? Number(lg.cost.value) : null,
      unit_cogs: lg.cogs && lg.cogs.value != null ? Number(lg.cogs.value) : null,
      um: line.displayUom || line.smallestUom || 'ea', um_qty: Number(line.displayUomQty) || 1,
      line_status: String(line.status || ''),
      // Eclipse line comments (lines[].comments[].comment), in Eclipse's order.
      // Line-level, so every generation's copy of the line has the same ones.
      // A comment may hold line breaks (e.g. "test\nRequested QTY: 1 UOM: ea").
      comments: (Array.isArray(line.comments) ? line.comments : [])
        .map((cm) => String((cm && cm.comment) || '').trim()).filter(Boolean),
    });
  }
}

const genBody = (gen) => {
  const status = String(gen.status || '');
  const gid = String(gen.generationId);
  return {
    e_sorder_id: v.oid + '.' + pad(gid),
    generation_id: Number(gid),
    // Eclipse's invoice number for this generation (invoiceNumber; invoiceId
    // is null in live responses). Cancelled gens can carry one too.
    invoice_number: gen.invoiceNumber != null ? Number(gen.invoiceNumber) : null,
    full_invoice_id: gen.fullInvoiceID || '',
    status,
    // Only a Bid can have its lines changed; Invoice and Cancel are final.
    editable: status === 'Bid',
    cancellable: status !== 'Invoice' && status !== 'Cancel',
    bill_to_id: String(gen.billToId || ''),
    ship_to_id: String(gen.shipToId || ''),
    ship_to_name: gen.shipToName || '',
    ship_branch: String(gen.shipBranch || ''),
    price_branch: String(gen.priceBranch || ''),
    ship_via: gen.shipVia || '',
    order_date: gen.orderDate || '',
    ship_date: gen.shipDate || '',
    required_date: gen.requiredDate || '',
    po: gen.poNumber || '',
    release: gen.releaseNumber || '',
    internal_notes: gen.internalNotes || '',
    shipping_instructions: gen.shippingInstructions || '',
    writer: gen.writer || '',
    outside_sales: gen.outsideSalesperson || '',
    inside_sales: gen.insideSalesperson || '',
    // Eclipse print status code as stored (values seen: N, Q, H, P, A; meanings unconfirmed).
    print_status: gen.printStatus || '',
    sales_total: money(gen.salesTotal),
    // Billable freight, tax and the order total, as Eclipse shows them
    // (salesTotal + freight + handling + tax = total on 99% of 2026 gens).
    freight_in: money(gen.freightInBillable),
    freight_out: money(gen.freightOutBillable),
    handling: (money(gen.handlingInBillable) || 0) + (money(gen.handlingOutBillable) || 0),
    tax_total: money(gen.taxTotal),
    order_total: money(gen.total),
    lines: linesByGen[gid] || [],
    // HubSpot deal for this generation ('' when there is none or the read failed).
    hs_deal_id: (deals[v.oid + '.' + pad(gid)] || {}).id || '',
    hs_deal_name: ((deals[v.oid + '.' + pad(gid)] || {}).properties || {}).dealname || '',
    tracking_details: ((deals[v.oid + '.' + pad(gid)] || {}).properties || {}).delivery_details || '',
    tracking_link: ((deals[v.oid + '.' + pad(gid)] || {}).properties || {}).delivery_tracking_link || '',
  };
};

const generations = so.generations.map(genBody).sort((a, b) => a.generation_id - b.generation_id);
const selected = v.genId ? generations.find((g) => String(g.generation_id) === v.genId) : generations[0];
if (!selected) return fail(404, 'Order ' + v.oid + ' has no generation ' + v.genId + '.', 'getSalesOrder');
return [{ json: { ok: true, statusCode: 200, body: {
  success: true,
  ...selected,
  order_id: v.oid,
  // Order-level last change (Eclipse has no per-generation timestamp).
  last_modified: so.lastUpdateDateTime || '',
  last_modified_by: so.lastUpdateUser || '',
  // Set when the HubSpot deal read failed (the order still loads).
  hubspot_error: hsResp.error ? String(hsResp.error) : '',
  generations,
} } }];
